import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";
import { env } from "./env.ts";

/**
 * AES-256-GCM for secrets at rest (e.g. AI API keys). The key comes from
 * MASTER_KEY (64 hex chars), generated by install.sh. Format: v1:<iv>:<tag>:<data>.
 */

function key(): Buffer {
  if (!/^[0-9a-fA-F]{64}$/.test(env.masterKey)) {
    throw new Error("服务器没有配置有效的 MASTER_KEY（64 位十六进制），无法加密保存密钥。请在配置文件中设置后重启。");
  }
  return Buffer.from(env.masterKey, "hex");
}

export const canEncrypt = () => /^[0-9a-fA-F]{64}$/.test(env.masterKey);

export function encrypt(plain: string): string {
  const iv = randomBytes(12);
  const c = createCipheriv("aes-256-gcm", key(), iv);
  const data = Buffer.concat([c.update(plain, "utf8"), c.final()]);
  return ["v1", iv.toString("base64"), c.getAuthTag().toString("base64"), data.toString("base64")].join(":");
}

export function decrypt(blob: string): string {
  const [v, iv, tag, data] = blob.split(":");
  if (v !== "v1") throw new Error("未知的密文格式");
  const d = createDecipheriv("aes-256-gcm", key(), Buffer.from(iv, "base64"));
  d.setAuthTag(Buffer.from(tag, "base64"));
  return Buffer.concat([d.update(Buffer.from(data, "base64")), d.final()]).toString("utf8");
}
